package com.estradaplay.patriota;
import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import org.json.*;import java.text.*;import java.util.*;
public final class TripHistoryActivity extends ComponentActivity{private final int BG=Color.rgb(9,5,7),TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38),BORDER=Color.rgb(76,38,43),GREEN=Color.rgb(69,212,131);@Override protected void onCreate(Bundle b){super.onCreate(b);showHistory();}private void showHistory(){ScrollView sv=new ScrollView(this);LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(18),dp(18),dp(18),dp(30));page.setBackgroundColor(BG);sv.addView(page);setContentView(UnifiedAppShell.wrap(this,"trip",sv));page.addView(t("HISTÓRICO + REPLAY",26,TEXT,true));page.addView(t("Percurso amostrado, linha do tempo, custos e qualidade ficam neste aparelho.",12,MUTED,false));JSONArray a=TripRecorder.history(this);if(a.length()==0)page.addView(t("Nenhuma viagem registrada ainda.",15,MUTED,false));for(int i=0;i<a.length();i++){final int idx=i;JSONObject o=a.optJSONObject(i);if(o==null)continue;LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(14),dp(13),dp(14),dp(13));c.setBackground(box(Color.rgb(22,10,13),12,BORDER));long start=o.optLong("started_at");double km=o.optDouble("distance_m")/1000.0;long dur=o.optLong("duration_ms");String date=new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(new Date(start));c.addView(t(date,13,RED,true));c.addView(t(String.format(Locale.getDefault(),"%.1f km · %s · máxima %.0f km/h",km,duration(dur),o.optDouble("max_speed")),16,TEXT,true));c.addView(t("Radares "+o.optInt("radars")+" · Quebra-molas "+o.optInt("bumps")+" · Câmeras "+o.optInt("cameras")+" · Impactos "+o.optInt("road_impacts"),11,MUTED,false));int q=o.optInt("road_quality_score",100);c.addView(t("QUALIDADE ESTIMADA · "+q+"/100",12,q>=75?GREEN:(q>=50?Color.rgb(226,185,76):RED),true));double fuel=o.optDouble("fuel_l",0),cost=o.optDouble("fuel_cost",0);if(fuel>0)c.addView(t(String.format(Locale.getDefault(),"Combustível %.1f L%s",fuel,cost>0?String.format(Locale.getDefault()," · R$ %.2f",cost):""),11,MUTED,false));Button replay=new Button(this);replay.setText("ABRIR REPLAY");replay.setOnClickListener(v->startActivity(new Intent(this,TripReplayActivity.class).putExtra("trip_index",idx)));c.addView(replay,new LinearLayout.LayoutParams(-1,dp(48)));JSONArray tl=o.optJSONArray("timeline");if(tl!=null&&tl.length()>0){c.addView(t("LINHA DO TEMPO",10,RED,true));for(int x=Math.max(0,tl.length()-12);x<tl.length();x++){JSONObject e=tl.optJSONObject(x);if(e==null)continue;String tm=new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(e.optLong("at")));c.addView(t(tm+" · "+e.optString("label",e.optString("type")),10,MUTED,false));}}page.addView(c);m(c,0,10,0,0);}Button clear=new Button(this);clear.setText("LIMPAR HISTÓRICO");clear.setOnClickListener(v->{TripRecorder.clear(this);showHistory();});page.addView(clear,new LinearLayout.LayoutParams(-1,dp(50)));}private String duration(long ms){long min=Math.max(0,ms/60000);return(min/60)+"h "+(min%60)+"min";}private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private GradientDrawable box(int c,int r,int st){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));d.setStroke(dp(1),st);return d;}private void m(View v,int l,int t,int r,int b){if(v.getLayoutParams() instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)v.getLayoutParams();p.setMargins(dp(l),dp(t),dp(r),dp(b));v.setLayoutParams(p);}}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}}
